// getCachedCertificate serializes CSRs for a user and never reuses a certificate
// within one minute of its expiry.
func (f *Forwarder) getCachedCertificate(ctx authContext) (*tls.Config, error) {
	key := ctx.key()
	for {
		f.Lock()
		cached, ok := f.certificates.Get(key)
		if ok {
			config := cached.(*tls.Config)
			cert, err := x509.ParseCertificate(config.Certificates[0].Certificate[0])
			if err == nil && cert.NotAfter.After(f.Clock.Now().Add(time.Minute)) {
				f.Unlock()
				return config, nil
			}
			f.certificates.Remove(key)
		}
		f.Unlock()

		requestCtx, done := f.getOrCreateRequestContext(key)
		if done == nil {
			select {
			case <-requestCtx.Done():
				continue
			case <-f.ctx.Done():
				return nil, trace.BadParameter("forwarder is closing, aborting the request")
			}
		}
		// A request may have populated the cache between the lookup above and
		// acquiring the CSR slot. Check it again before contacting auth.
		f.Lock()
		cached, ok = f.certificates.Get(key)
		if ok {
			config := cached.(*tls.Config)
			cert, err := x509.ParseCertificate(config.Certificates[0].Certificate[0])
			if err == nil && cert.NotAfter.After(f.Clock.Now().Add(time.Minute)) {
				f.Unlock()
				done()
				return config, nil
			}
			f.certificates.Remove(key)
		}
		f.Unlock()
		config, err := f.requestCertificate(ctx)
		if err != nil {
			done()
			return nil, trace.Wrap(err)
		}
		cert, err := x509.ParseCertificate(config.Certificates[0].Certificate[0])
		if err != nil {
			done()
			return nil, trace.Wrap(err)
		}
		ttl := cert.NotAfter.Sub(f.Clock.Now()) - time.Minute
		if ttl > ctx.sessionTTL {
			ttl = ctx.sessionTTL
		}
		if ttl > 0 {
			f.Lock()
			err = f.certificates.Set(key, config, ttl)
			f.Unlock()
		}
		done()
		if err != nil {
			return nil, trace.Wrap(err)
		}
		return config, nil
	}
}
