/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
p=Path('lib/kube/proxy/forwarder_test.go');s=p.read_text();s=s.replace('''	lastCert *x509.Certificate
}''','''	lastCert *x509.Certificate
	csrCount int
}''');s=s.replace('''func (c *mockCSRClient) ProcessKubeCSR(csr auth.KubeCSR) (*auth.KubeCSRResponse, error) {
	c.gotCSR = csr''','''func (c *mockCSRClient) ProcessKubeCSR(csr auth.KubeCSR) (*auth.KubeCSRResponse, error) {
	c.csrCount++
	c.gotCSR = csr''');needle='// mockCSRClient to intercept ProcessKubeCSR requests, record them and return a\\n';test='''func TestConcurrentCertificateRequests(t *testing.T) {
	client, err := newMockCSRClient()
	require.NoError(t, err)
	certificates, err := ttlmap.New(defaults.ClientCacheSize)
	require.NoError(t, err)
	user, err := services.NewUser(\"bob\")
	require.NoError(t, err)
	f := &Forwarder{
		ForwarderConfig: ForwarderConfig{Keygen: testauthority.New(), AuthClient: client, Clock: clockwork.NewRealClock()},
		log: logrus.New(),
		certificates: certificates,
		activeRequests: make(map[string]context.Context),
		ctx: context.Background(),
	}
	ctx := authContext{
		Context: auth.Context{User: user, Identity: auth.WrapIdentity(tlsca.Identity{Username: \"bob\"})},
		teleportCluster: teleportClusterClient{name: \"remote\", isRemote: true},
		sessionTTL: time.Hour,
	}
	results := make(chan *tls.Config, 8)
	errors := make(chan error, 8)
	for i := 0; i < 8; i++ {
		go func() {
			cert, err := f.getCachedCertificate(ctx)
			results <- cert
			errors <- err
		}()
	}
	var first *tls.Config
	for i := 0; i < 8; i++ {
		require.NoError(t, <-errors)
		cert := <-results
		if first == nil {
			first = cert
		} else {
			require.Same(t, first, cert)
		}
	}
	require.Equal(t, 1, client.csrCount)
}

